param([Parameter(Mandatory)][string]$ConfigurationFile,[Parameter(Mandatory)][string]$ConfigurationSignatureFile,[Parameter(Mandatory)][string]$TrustedPublicKeyFile,[Parameter(Mandatory)][string]$ExpectedSigningKeyId,[switch]$ValidateOnly)
$ErrorActionPreference='Stop';. "$PSScriptRoot/BackupRestore.Common.ps1";$required=@('DeploymentRoot','ConfirmDeploymentRoot','DeploymentId','SecretRoot','StatePrivateKeyFile','StatePublicKeyFile','StateSignerKeyId','CurrentSlotDirectory','CurrentTrustedPublicKeyFile','CurrentExpectedSigningKeyId','CandidateSlotDirectory','CandidateTrustedPublicKeyFile','CandidateExpectedSigningKeyId','ExpectedPackageSupplier','ExpectedSbomNamespaceBase','PlanFile','RequesterPublicKeyFile','ExpectedRequesterKeyId','ApproverPublicKeyFile','ExpectedApproverKeyId','MonitoringPublicKeyFile','ExpectedMonitoringKeyId','ObservationFile','ObservationSignatureFile','ExpectedWavePercent','ServerArguments');$forbidden=@('ExitAfterSuccessfulSwitch','TestOnlySuppressCurrentShutdown','AllowTestPlan','AllowDirtyTestArtifact')
$file=[IO.Path]::GetFullPath($ConfigurationFile);$bytes=[IO.File]::ReadAllBytes($file);Test-BackupSignature $bytes ([IO.File]::ReadAllBytes([IO.Path]::GetFullPath($ConfigurationSignatureFile))) $TrustedPublicKeyFile 'Supervisor configuration';$fingerprint=Get-BackupKeyFingerprint $TrustedPublicKeyFile 'Supervisor configuration' $false;$config=[Text.Encoding]::UTF8.GetString($bytes)|ConvertFrom-Json -Depth 20 -DateKind String;if($config.SchemaVersion-ne1-or$config.Product-cne'ET.Server'-or$config.ArtifactType-cne'ServerSupervisorConfiguration'-or$config.SignerKeyId-cne$ExpectedSigningKeyId-or$config.SignerPublicKeySha256-cne$fingerprint){throw 'Supervisor configuration identity is invalid'};$names=@($config.SupervisorParameters.PSObject.Properties.Name);foreach($name in $required){if($name -notin $names-or[string]::IsNullOrWhiteSpace([string]$config.SupervisorParameters.$name)){throw "Supervisor parameter is missing: $name"}};foreach($name in $forbidden){if($name -in $names){throw "Test-only supervisor parameter is forbidden: $name"}};$parameters=@{};foreach($property in $config.SupervisorParameters.PSObject.Properties){$parameters[$property.Name]=$property.Value};if($ValidateOnly){[ordered]@{Passed=$true;ServiceId=$config.ServiceId;DeploymentId=$parameters.DeploymentId;ConfigurationSha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}|ConvertTo-Json;exit 0};& "$PSScriptRoot/Invoke-ServerSlotSupervisor.ps1" @parameters;exit $LASTEXITCODE
